public static void main(String[] args) {

    InputStream source = System.in;
    Scanner sc = new Scanner(source);

    int N = sc.nextInt();
    int T = sc.nextInt();

    int[] yoko = new int[N];
    int[] tate = new int[N];
    int naname_左上から右下 = 0;
    int naname_右上から左下 = 0;

    for (int i = 0; i < T; i++) {
        int t = sc.nextInt();
        int x = (t - 1) / N;
        int y = (t - 1) % N;

        yoko[y]++;
        tate[x]++;
        if (x == y) {
            naname_左上から右下++;
        }
        if (x + y == N - 1) {
            naname_右上から左下++;
        }

        if (yoko[y] == N || tate[x] == N || naname_左上から右下 == N || naname_右上から左下 == N) {
            System.out.println(i + 1);
            return;
        }
    }
    System.out.println("-1");
}
